from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove any spaces in the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and separate the groups of nested parentheses
    groups = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == "(":
            open_braces += 1
        elif char == ")":
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Check if each group is balanced
    for group in groups:
        if group.count("(") != group.count(")"):
            return "Invalid input: Unbalanced parentheses"

    # Step 4: Ignore any nested groups within each other
    filtered_groups = []
    for group in groups:
        if all("(" not in inner_group for inner_group in filtered_groups):
            filtered_groups.append(group)

    # Step 5: Return the list of separated groups
    return filtered_groups

